# 构建最长前缀匹配正则
_S2T_REGEX = re.compile('|'.join(sorted(map(re.escape, _S2T_PHRASES.keys()), key=len, reverse=True)))
_T2S_REGEX = re.compile('|'.join(sorted(map(re.escape, _T2S_PHRASES.keys()), key=len, reverse=True)))


def is_japanese_text(text: str) -> bool:
    """检测字符串中是否包含日文平假名、片假名。"""
    if not text:
        return False
    return bool(_JAPANESE_KANA_RE.search(text))


def is_known_jpop_artist(artist_name: str) -> bool:
    """判断艺术家名称是否属于知名日文艺术家/乐队名单。"""
    if not artist_name:
        return False
    clean = artist_name.strip()
    return clean in KNOWN_JPOP_ARTISTS


def to_simplified(text: str, *, preserve_jpop: bool = False) -> str:
    """将繁体汉字转为简体汉字（支持日文汉字保护与词组消歧）。"""
    if not text:
        return ""
    if preserve_jpop and (is_japanese_text(text) or is_known_jpop_artist(text)):
        return text

    last = 0
    parts: list[str] = []
    for m in _T2S_REGEX.finditer(text):
        if m.start() > last:
            parts.append(text[last:m.start()].translate(_TRAD_TO_SIMP_TABLE))
        parts.append(_T2S_PHRASES[m.group(0)])
        last = m.end()
    if last < len(text):
        parts.append(text[last:].translate(_TRAD_TO_SIMP_TABLE))
    return "".join(parts)


def to_traditional(text: str, *, preserve_jpop: bool = False) -> str:
    """将简体汉字转为繁体汉字（支持日文汉字保护与词组消歧）。"""
    if not text:
        return ""
    if preserve_jpop and (is_japanese_text(text) or is_known_jpop_artist(text)):
        return text

    last = 0
    parts: list[str] = []
    for m in _S2T_REGEX.finditer(text):
        if m.start() > last:
            parts.append(text[last:m.start()].translate(_SIMP_TO_TRAD_TABLE))
        parts.append(_S2T_PHRASES[m.group(0)])
        last = m.end()
    if last < len(text):
        parts.append(text[last:].translate(_SIMP_TO_TRAD_TABLE))
    return "".join(parts)


def convert_chinese(
    text: str,
    direction: str = 't2s',
    *,
    preserve_jpop: bool = True,
    custom_dict: dict[str, str] | None = None,
) -> str:
    """统一简繁转换入口。

    :param text: 输入文本
    :param direction: 't2s' (繁转简) 或 's2t' (简转繁)
    :param preserve_jpop: 是否启用日文汉字防误伤守卫（默认开启）
    :param custom_dict: 用户自定义优先词典映射
    """
    if not text:
        return ""
    if custom_dict and text in custom_dict:
        return custom_dict[text]

    if direction == 's2t':
        return to_traditional(text, preserve_jpop=preserve_jpop)
    return to_simplified(text, preserve_jpop=preserve_jpop)


def convert_lrc(
    lrc_text: str,
    direction: str = 't2s',
    *,
    preserve_jpop: bool = True,
    custom_dict: dict[str, str] | None = None,
) -> str:
    """结构化同步歌词（LRC）简繁转换。

    精准保留 [mm:ss.xx] 时间轴标签，仅转换歌词文本正文与元数据字段内容（ti/ar/al）。
    """
    if not lrc_text:
        return ""

    lines = lrc_text.replace('\r\n', '\n').replace('\r', '\n').split('\n')
    out_lines: list[str] = []

    # 匹配时间戳前缀，如 [01:23.45] 或 [01:23.45][02:34.56]
    ts_re = re.compile(r'^((?:\[\d{1,2}:\d{2}(?:\.\d{1,3})?\])+)(.*)$')
    # 匹配元数据标签，如 [ti:小城故事], [ar:鄧麗君], [al:島國之情歌 第六集]
    tag_re = re.compile(r'^(\[(?:ti|ar|al|by|re|ve):)(.*)(\])$', re.IGNORECASE)

    for line in lines:
        if not line.strip():
            out_lines.append(line)
            continue

        m_ts = ts_re.match(line)
        if m_ts:
            ts_prefix = m_ts.group(1)
            lyric_body = m_ts.group(2)
            converted_body = convert_chinese(
                lyric_body, direction, preserve_jpop=preserve_jpop, custom_dict=custom_dict
            )
            out_lines.append(ts_prefix + converted_body)
            continue

        m_tag = tag_re.match(line)
        if m_tag:
            prefix = m_tag.group(1)
            val = m_tag.group(2)
            suffix = m_tag.group(3)
            converted_val = convert_chinese(
                val, direction, preserve_jpop=preserve_jpop, custom_dict=custom_dict
            )
            out_lines.append(prefix + converted_val + suffix)
            continue

        # 普通文本行（无时间轴歌词）
        out_lines.append(
            convert_chinese(line, direction, preserve_jpop=preserve_jpop, custom_dict=custom_dict)
        )

    return '\n'.join(out_lines)


def diff_tags(
    track_or_dict: Any,
    fields: Iterable[str],
    direction: str = 't2s',
    *,
    preserve_jpop: bool = True,
    custom_dict: dict[str, str] | None = None,
) -> list[tuple[str, str, str]]:
    """比对指定字段转换前后的差异。

    返回: [(字段名, 原始值, 转换后值), ...] (仅包含发生变化的字段)
    """
    diffs: list[tuple[str, str, str]] = []

    is_dict = isinstance(track_or_dict, dict)
    for f in fields:
        orig = track_or_dict.get(f, '') if is_dict else getattr(track_or_dict, f, '')
        if not isinstance(orig, str) or not orig.strip():
            continue

        # 若是艺术家相关字段且命中日文保护，自动跳过
        if preserve_jpop and f in ('artist', 'albumartist') and is_known_jpop_artist(orig):
            continue

        converted = convert_chinese(
            orig, direction, preserve_jpop=preserve_jpop, custom_dict=custom_dict
        )
        if orig != converted:
            diffs.append((f, orig, converted))

    return diffs


def convert_track_tags(
    track_or_dict: Any,
    fields: Iterable[str],
    direction: str = 't2s',
    *,
    preserve_jpop: bool = True,
    custom_dict: dict[str, str] | None = None,
) -> dict[str, str]:
    """生成音轨待更新的标签键值对字典（仅包含发生改变的字段）。"""
    diffs = diff_tags(
        track_or_dict, fields, direction, preserve_jpop=preserve_jpop, custom_dict=custom_dict
    )
    return {fld: new_v for fld, _, new_v in diffs}
